// Uebernimmt die im Edge-App-Portal getroffene Wechselrichter-Auswahl
// (retained auf edge/inverter/config, von vp-inverter-config geparst) in den
// Flow-Kontext. Der Router unten liest sie bei jedem Poll - so verdrahtet sich
// der Flow selbst, ohne Edit pro Kunde. payload === null => Auswahl geloescht.
const sel = msg.payload || null;
flow.set('inverter_config', sel);
if (sel) {
  node.status({ fill: 'green', shape: 'dot', text: (sel.label || sel.brand || sel.family) + ' (' + sel.communication + ')' });
} else {
  node.status({ fill: 'grey', shape: 'ring', text: 'Auswahl zurueckgesetzt' });
}
return null;

// Router / Leseplan - das Herzstueck der Selbstverdrahtung: liest die aktive
// Wechselrichter-Auswahl aus dem Flow-Kontext (von vp-inverter-config gesetzt)
// und waehlt GENAU EINEN Lesepfad. Synchron gehalten mit
// edge-app/nodered/inverter-routing.js (route) + den Registerkarten aus
// deye/deye-decode.js und modbus-tcp.js.
//   Ausgang 1: Deye Solarman-V5   (msg.deye)
//   Ausgang 2: generisches Modbus (msg.mb)
//   Ausgang 3: untaetig           (keine/unbekannte Auswahl)
const DEYE_READS = {
  string:    [{ start: 0x0050, count: 0x0002 }],
  hybrid_1p: [{ start: 0x00a9, count: 0x0016 }],
  hybrid_3p: [{ start: 0x024c, count: 0x0058 }],
  micro:     [{ start: 0x0056, count: 0x0002 }]
};
const MODBUS_PROFILES = { sunspec: { fc: 3, addr: 0, count: 9 } };
const num = (v, d) => { const n = typeof v === 'string' ? Number(v.trim()) : v; return (typeof n === 'number' && isFinite(n)) ? n : d; };
const idle = (reason) => { node.status({ fill: 'grey', shape: 'ring', text: reason }); msg.idle = reason; return [null, null, msg]; };
const sel = flow.get('inverter_config');
if (!sel) return idle('keine Auswahl');
const conn = sel.connection || {};
const ip = (typeof conn.ip === 'string' ? conn.ip : '').trim();
if (!ip) return idle('keine IP-Adresse');
if (sel.communication === 'solarman_v5') {
  const reads = DEYE_READS[sel.family];
  if (!reads) return idle('unbekannte Deye-Familie: ' + sel.family);
  const serial = conn.serial;
  if (serial === undefined || serial === null || serial === '' || !(Number(serial) > 0)) return idle('Datenlogger-Seriennummer fehlt');
  const port = num(conn.port, 8899);
  const cfg = {
    ip, port, serial,
    mb_slave_id: num(conn.mb_slave_id, 1),
    family: sel.family,
    invert_grid_sign: !!conn.invert_grid_sign,
    invert_batt_sign: !!conn.invert_batt_sign,
    power_scale: num(conn.power_scale, 1) > 0 ? num(conn.power_scale, 1) : 1
  };
  msg.deye = { cfg, target: ip + ':' + port, reads: reads.map((r) => ({ start: r.start, count: r.count })), i: 0, blocks: [] };
  node.status({ fill: 'blue', shape: 'dot', text: 'Deye ' + sel.family + ' -> Solarman-V5' });
  return [msg, null, null];
}
if (sel.communication === 'modbus_tcp') {
  const read = MODBUS_PROFILES[sel.family];
  if (!read) return idle('unbekanntes Modbus-Profil: ' + sel.family);
  const port = num(conn.port, 502);
  msg.mb = { conn: { ip, port, unit_id: num(conn.unit_id, 1) }, profile: sel.family, read: { fc: read.fc, addr: read.addr, count: read.count }, target: ip + ':' + port };
  node.status({ fill: 'blue', shape: 'dot', text: 'Modbus ' + sel.family + ' @ ' + ip + ':' + port });
  return [null, msg, null];
}
return idle('unbekannte Kommunikationsmethode');

// Solarman-V5-Transport: Modbus-RTU im Solarman-V5-Rahmen ueber TCP 8899 - die
// ROBUSTE Deye-Anbindung (ersetzt die flaky AT-CLI ueber UDP 48899). Eine
// einzige, geordnete TCP-Verbindung pro Poll (der Logger erlaubt nur EINEN
// Client), sequenzielle Bloecke, Reconnect je Poll.
//
// Traegt eine KOPIE von edge-app/nodered/deye/solarman-v5.js (ein Node-RED-Flow
// ist self-contained JSON und kann keine Repo-Datei zur Laufzeit requiren).
// Quelle der Wahrheit + Offline-Tests: deye/solarman-v5.js - beide synchron halten.
const net = global.get('net');
if (!net) {
  node.status({ fill: 'red', shape: 'ring', text: 'net fehlt (settings.js)' });
  node.error('functionGlobalContext.net in settings.js setzen (siehe DEYE.md)', msg);
  return null;
}
const ctx = msg.deye;
if (!ctx) return null;
const cfg = ctx.cfg;
const serial = cfg.serial;
if (serial === undefined || serial === null || serial === '' || !(Number(serial) > 0)) {
  node.status({ fill: 'red', shape: 'ring', text: 'Logger-Serial fehlt' });
  node.error('cfg.serial (Datalogger-Seriennummer, Zahl) ist fuer solarman_v5 erforderlich', msg);
  return null;
}
const sn = Number(serial) >>> 0;
const port = cfg.port || 8899;
const slaveId = cfg.mb_slave_id || 1;
const timeoutMs = cfg.timeout_ms || 8000;

// --- codec (Kopie von deye/solarman-v5.js) ---
const modbusCrc16 = (buf) => { let c = 0xffff; for (let i = 0; i < buf.length; i++) { c ^= buf[i]; for (let b = 0; b < 8; b++) c = (c & 1) ? ((c >>> 1) ^ 0xa001) : (c >>> 1); } return c & 0xffff; };
const readReq = (sl, start, count) => { const b = Buffer.alloc(6); b[0] = sl & 0xff; b[1] = 0x03; b.writeUInt16BE(start & 0xffff, 2); b.writeUInt16BE(count & 0xffff, 4); const c = modbusCrc16(b); return Buffer.concat([b, Buffer.from([c & 0xff, (c >> 8) & 0xff])]); };
const v5cs = (f) => { let s = 0; for (let i = 1; i < f.length - 2; i++) s = (s + f[i]) & 0xff; return s & 0xff; };
const buildReq = (seq, mb) => { const len = 15 + mb.length; const h = Buffer.alloc(11); h[0] = 0xa5; h.writeUInt16LE(len, 1); h.writeUInt16LE(0x4510, 3); h.writeUInt16LE(seq & 0xffff, 5); h.writeUInt32LE(sn, 7); const pre = Buffer.alloc(15); pre[0] = 0x02; const fr = Buffer.concat([h, pre, mb, Buffer.from([0x00, 0x15])]); fr[fr.length - 2] = v5cs(fr); return fr; };
const frameLen = (buf) => { if (buf.length < 3) return null; if (buf[0] !== 0xa5) throw new Error('Startbyte'); return 11 + buf.readUInt16LE(1) + 2; };
const parseResp = (buf) => {
  if (buf.length < 13) throw new Error('Frame zu kurz');
  if (buf[0] !== 0xa5) throw new Error('Startbyte');
  const total = 11 + buf.readUInt16LE(1) + 2;
  if (buf.length < total) throw new Error('Frame kuerzer als Laengenfeld');
  const f = buf.slice(0, total);
  if (f[f.length - 1] !== 0x15) throw new Error('Endbyte');
  if (v5cs(f) !== f[f.length - 2]) throw new Error('V5-Pruefsumme');
  if (f.readUInt16LE(3) !== 0x1510) throw new Error('Controlcode 0x' + f.readUInt16LE(3).toString(16));
  if (f.readUInt32LE(7) !== sn) throw new Error('Logger-Serial weicht ab: ' + f.readUInt32LE(7));
  const mb = f.slice(25, f.length - 2);
  if (mb.length < 5) throw new Error('Modbus zu kurz');
  return mb;
};
const parseModbus = (mb) => {
  if (mb.readUInt16LE(mb.length - 2) !== modbusCrc16(mb.slice(0, mb.length - 2))) throw new Error('Modbus-CRC');
  if (mb[1] & 0x80) throw new Error('Modbus-Ausnahme 0x' + mb[2].toString(16));
  if (mb[1] !== 0x03) throw new Error('Modbus-Funktion 0x' + mb[1].toString(16));
  const bc = mb[2]; const regs = []; for (let i = 0; i < bc >> 1; i++) regs.push(mb.readUInt16BE(3 + i * 2)); return regs;
};

// --- eine Leseanfrage ueber den offenen Socket (TCP-Segmente reassemblieren) ---
const readBlock = (sock, start, count, seq) => new Promise((resolve, reject) => {
  let acc = Buffer.alloc(0);
  const t = setTimeout(() => { cleanup(); reject(new Error('Timeout')); }, timeoutMs);
  const onData = (chunk) => {
    acc = Buffer.concat([acc, chunk]);
    let need; try { need = frameLen(acc); } catch (e) { cleanup(); return reject(e); }
    if (need !== null && acc.length >= need) { cleanup(); try { resolve(parseModbus(parseResp(acc.slice(0, need)))); } catch (e) { reject(e); } }
  };
  const onErr = (e) => { cleanup(); reject(e); };
  const cleanup = () => { clearTimeout(t); sock.removeListener('data', onData); sock.removeListener('error', onErr); };
  sock.on('data', onData); sock.on('error', onErr);
  sock.write(buildReq(seq, readReq(slaveId, start, count)));
});

let seq = context.get('seq') || 0;
return new Promise((resolve) => {
  const sock = new net.Socket();
  sock.setNoDelay(true);
  let done = false;
  const finish = (err) => {
    if (done) return; done = true;
    try { sock.destroy(); } catch (e) { /* ignore */ }
    if (err) { node.status({ fill: 'red', shape: 'ring', text: 'V5: ' + err.message }); resolve(null); }
    else { resolve(msg); }
  };
  const connTimer = setTimeout(() => finish(new Error('Verbindungs-Timeout')), timeoutMs);
  sock.once('error', (e) => { clearTimeout(connTimer); finish(e); });
  sock.connect(port, cfg.ip, async () => {
    clearTimeout(connTimer);
    try {
      for (const r of ctx.reads) { seq = (seq + 1) & 0xffff; ctx.blocks.push({ start: r.start, regs: await readBlock(sock, r.start, r.count, seq) }); }
      context.set('seq', seq);
      finish();
    } catch (e) { finish(e); }
  });
});

// Decodiert die gelesenen Register in die flache edge/telemetry-Nachricht.
// Nur die kanonischen Cloud-Felder gehen an vp-telemetrie; die Batterieleistung
// (batt_kw) ist reine Kalibrierhilfe (Status/Debug) - die Cloud leitet sie aus
// der Leistungsbilanz ab. Quelle der Wahrheit + Tests:
// edge-app/nodered/deye/deye-decode.js
const ctx = msg.deye;
if (!ctx || !ctx.blocks.length) { node.status({ fill: 'red', shape: 'ring', text: 'keine Register' }); return null; }
const cfg = ctx.cfg;
const FAMILIES = {
  string: { hasBattery: false, fields: {
    pv:   { addr: 0x0050, bits: 32, signed: false, scale: 0.1 } } },
  hybrid_1p: { hasBattery: true, fields: {
    grid: { addr: 0x00a9, bits: 16, signed: true,  scale: 1 },
    load: { addr: 0x00b2, bits: 16, signed: false, scale: 1 },
    soc:  { addr: 0x00b8, bits: 16, signed: false, scale: 1, kind: 'pct' },
    pv:   { addrs: [0x00ba, 0x00bb], bits: 16, signed: false, scale: 1, sum: true },
    batt: { addr: 0x00be, bits: 16, signed: true,  scale: 1 } } },
  hybrid_3p: { hasBattery: true, fields: {
    soc:  { addr: 0x024c, bits: 16, signed: false, scale: 1, kind: 'pct' },
    batt: { addr: 0x024e, bits: 16, signed: true,  scale: 1 },
    grid: { addr: 0x0271, bits: 16, signed: true,  scale: 1 },
    load: { addr: 0x028d, bits: 16, signed: false, scale: 1 },
    pv:   { addrs: [0x02a0, 0x02a1, 0x02a2, 0x02a3], bits: 16, signed: false, scale: 1, sum: true } } },
  micro: { hasBattery: false, fields: {
    pv: { addr: 0x0056, bits: 32, signed: false, scale: 0.1 } } }
};
const fam = FAMILIES[cfg.family];
if (!fam) { node.status({ fill: 'red', shape: 'ring', text: 'unbekannte Familie' }); return null; }
const s16 = (v) => { v &= 0xffff; return v > 0x7fff ? v - 0x10000 : v; };
const r3 = (x) => Math.round(x * 1000) / 1000;
const r1 = (x) => Math.round(x * 10) / 10;
// SoC-Plausibilitaetspruefung (drop-don't-fabricate): eine Batterie-SoC ist
// physikalisch 0..100 %, und ein echtes BMS meldet nie exakt 0. Ein Solarman-
// Logger, der den Wechselrichter NICHT erreicht, antwortet trotzdem mit einem
// gueltigen (CRC-ok) Rahmen - meist ein Null-Block (die klassische naechtliche
// Leerantwort) oder ein voellig ueberzogener Wert. Wird das als soc_pct=0 bzw.
// soc_pct>100 uebernommen, entstehen die 0/100-Spikes in der SoC-Zeitreihe.
// Darum: unplausible SoC => ganzen Messwert verwerfen (kein Sample, nie eine 0).
const socPlausible = (p) => typeof p === 'number' && isFinite(p) && p > 0 && p <= 100;
const readReg = (addr) => {
  for (const b of ctx.blocks) { const o = addr - b.start; if (o >= 0 && o < b.regs.length) return b.regs[o]; }
  return undefined;
};
const fieldValue = (f) => {
  let raw;
  if (f.bits === 32) {
    const lo = readReg(f.addr), hi = readReg(f.addr + 1);
    if (lo === undefined || hi === undefined) return undefined;
    raw = hi * 65536 + lo; if (f.signed && raw > 0x7fffffff) raw -= 0x100000000;
  } else if (f.sum) {
    raw = 0; for (const a of f.addrs) { const v = readReg(a); if (v === undefined) return undefined; raw += f.signed ? s16(v) : (v & 0xffff); }
  } else {
    const v = readReg(f.addr); if (v === undefined) return undefined; raw = f.signed ? s16(v) : (v & 0xffff);
  }
  return raw * (f.scale === undefined ? 1 : f.scale);
};
const pscale = Number(cfg.power_scale) > 0 ? Number(cfg.power_scale) : 1;
const toKw = (w) => r3((w * pscale) / 1000);
const f = fam.fields;
const reading = { ts: new Date().toISOString() };
if (f.pv)   { const w = fieldValue(f.pv);   if (w !== undefined) reading.pv_power_kw = toKw(w); }
if (f.load) { const w = fieldValue(f.load); if (w !== undefined) reading.load_kw = toKw(w); }
if (f.grid) { let w = fieldValue(f.grid);   if (w !== undefined) { if (cfg.invert_grid_sign) w = -w; reading.power_kw = toKw(w); } }
if (fam.hasBattery && f.soc)  { const s = fieldValue(f.soc); if (!socPlausible(s)) { node.status({ fill: 'yellow', shape: 'ring', text: 'SoC unplausibel -> verworfen' }); return null; } reading.soc_pct = r1(s); }
let batt_kw;
if (fam.hasBattery && f.batt) { let w = fieldValue(f.batt);   if (w !== undefined) { if (cfg.invert_batt_sign) w = -w; batt_kw = toKw(w); } }
const keys = Object.keys(reading).filter((k) => k !== 'ts');
if (keys.length === 0) { node.status({ fill: 'yellow', shape: 'ring', text: 'keine Messwerte decodiert' }); return null; }
const pv = reading.pv_power_kw !== undefined ? reading.pv_power_kw.toFixed(1) : '?';
const soc = reading.soc_pct !== undefined ? (', SoC ' + reading.soc_pct.toFixed(0) + ' %') : '';
const bt = batt_kw !== undefined ? (', Batt ' + batt_kw.toFixed(1) + ' kW') : '';
node.status({ fill: 'green', shape: 'dot', text: 'pv ' + pv + ' kW' + soc + bt });
return [{ payload: reading }, { payload: true }];

// Generischer Modbus-TCP-Leser (FC3, Holding Registers): eine geordnete
// TCP-Verbindung pro Poll, ein Registerblock, TCP-Segmente reassembliert.
// Traegt eine KOPIE des Codecs aus edge-app/nodered/modbus-tcp.js
// (buildReadRequest/expectedFrameLength/parseReadResponse) - beide synchron
// halten (ein Node-RED-Flow ist self-contained JSON und kann keine Repo-Datei
// zur Laufzeit requiren). Quelle der Wahrheit + Offline-Tests: modbus-tcp.js.
const net = global.get('net');
if (!net) { node.status({ fill: 'red', shape: 'ring', text: 'net fehlt (settings.js)' }); node.error('functionGlobalContext.net in settings.js setzen', msg); return null; }
const mb = msg.mb;
if (!mb) return null;
const conn = mb.conn;
const unitId = conn.unit_id || 1;
const timeoutMs = conn.timeout_ms || 5000;
const buildReq = (txid, addr, count) => { const b = Buffer.alloc(12); b.writeUInt16BE(txid & 0xffff, 0); b.writeUInt16BE(0, 2); b.writeUInt16BE(6, 4); b[6] = unitId & 0xff; b[7] = 0x03; b.writeUInt16BE(addr & 0xffff, 8); b.writeUInt16BE(count & 0xffff, 10); return b; };
const frameLen = (buf) => (buf.length < 6 ? null : 6 + buf.readUInt16BE(4));
const parseResp = (buf, txid) => {
  if (buf.length < 9) throw new Error('Antwort zu kurz');
  if (buf.readUInt16BE(2) !== 0) throw new Error('Protokoll-ID');
  if (buf.readUInt16BE(0) !== (txid & 0xffff)) throw new Error('Transaktions-ID weicht ab');
  const fn = buf[7];
  if (fn & 0x80) throw new Error('Modbus-Ausnahme 0x' + (buf[8] || 0).toString(16));
  if (fn !== 0x03) throw new Error('Modbus-Funktion 0x' + fn.toString(16));
  const bc = buf[8];
  if (bc <= 0 || buf.length < 9 + bc) throw new Error('Nutzlast unvollstaendig');
  const regs = []; for (let i = 0; i < bc >> 1; i++) regs.push(buf.readUInt16BE(9 + i * 2)); return regs;
};
let txid = context.get('txid') || 0;
return new Promise((resolve) => {
  const sock = new net.Socket();
  sock.setNoDelay(true);
  let done = false;
  let acc = Buffer.alloc(0);
  const finish = (err) => { if (done) return; done = true; try { sock.destroy(); } catch (e) { /* ignore */ } if (err) { node.status({ fill: 'red', shape: 'ring', text: 'Modbus: ' + err.message }); resolve(null); } else { resolve(msg); } };
  const t = setTimeout(() => finish(new Error('Timeout')), timeoutMs);
  txid = (txid + 1) & 0xffff; context.set('txid', txid);
  sock.once('error', (e) => { clearTimeout(t); finish(e); });
  sock.connect(conn.port || 502, conn.ip, () => {
    sock.on('data', (chunk) => {
      acc = Buffer.concat([acc, chunk]);
      const need = frameLen(acc);
      if (need !== null && acc.length >= need) { clearTimeout(t); try { mb.regs = parseResp(acc.slice(0, need), txid); finish(); } catch (e) { finish(e); } }
    });
    sock.write(buildReq(txid, mb.read.addr, mb.read.count));
  });
});

// Decodiert den Modbus-Block laut Profil in die flache edge/telemetry-Nachricht.
// Traegt eine KOPIE der PROFILES aus edge-app/nodered/modbus-tcp.js - synchron
// halten. Ausgang 1: Messwerte fuer vp-telemetrie; Ausgang 2: true als Link-
// Lebenszeichen. Das Profil 'sunspec' entspricht dem kompakten Block des
// SunSpec-Simulators (edge/sim/sunspec-sim.js), FC3 Adr. 0..8.
const mb = msg.mb;
if (!mb || !Array.isArray(mb.regs)) { node.status({ fill: 'red', shape: 'ring', text: 'keine Register' }); return null; }
const s16 = (v) => { v &= 0xffff; return v > 0x7fff ? v - 0x10000 : v; };
const r3 = (x) => Math.round(x * 1000) / 1000;
const r1 = (x) => Math.round(x * 10) / 10;
const PROFILES = {
  sunspec: (regs) => {
    if (regs.length < 7) return null;
    const gridKw = s16(regs[0]) / 100;   // + Bezug / - Einspeisung
    const pvKw = s16(regs[1]) / 100;
    const loadKw = s16(regs[2]) / 100;
    const socPct = regs[4] / 10;
    const wmax = regs[5] / 100;          // beobachtete §14a-Begrenzung in %
    const gridConn = regs[6] / 100;
    const reading = { ts: new Date().toISOString(), power_kw: r3(gridKw), pv_power_kw: r3(pvKw), load_kw: r3(loadKw), soc_pct: r1(socPct), grid_limit_kw: r3((wmax / 100) * gridConn) };
    return { reading, batt_kw: r3(s16(regs[3]) / 100) };
  }
};
const dec = PROFILES[mb.profile];
if (!dec) { node.status({ fill: 'red', shape: 'ring', text: 'unbekanntes Profil: ' + mb.profile }); return null; }
const out = dec(mb.regs);
if (!out) { node.status({ fill: 'yellow', shape: 'ring', text: 'keine Messwerte decodiert' }); return null; }
const pv = out.reading.pv_power_kw !== undefined ? out.reading.pv_power_kw.toFixed(1) : '?';
const soc = out.reading.soc_pct !== undefined ? (', SoC ' + out.reading.soc_pct.toFixed(0) + ' %') : '';
node.status({ fill: 'green', shape: 'dot', text: 'pv ' + pv + ' kW' + soc });
return [{ payload: out.reading }, { payload: true }];

// Untaetig: keine oder unbekannte Auswahl. Setzt nur den Knotenstatus als
// sichtbaren Hinweis - es wird KEIN edge/status veroeffentlicht (sonst wuerde
// es im reinen Simulator-Betrieb mit dem Link-Status des Simulator-Tabs
// kollidieren). Sobald eine gueltige Auswahl retained eintrifft, laeuft der
// passende Lesepfad automatisch an.
node.status({ fill: 'grey', shape: 'ring', text: msg.idle || 'keine Auswahl' });
return null;

// Decode des FC3-Registerblocks (Adr. 0..8) des SunSpec-Simulators in die
// Messwerte für vp-telemetrie. Skalierung: edge/sim/sunspec-sim.js.
const r = msg.payload;
if (!Array.isArray(r) || r.length < 9) { return null; }
const s16 = (v) => (v > 32767 ? v - 65536 : v);
const grid_kw = s16(r[0]) / 100;   // + Bezug / - Einspeisung
const pv_kw = s16(r[1]) / 100;
const load_kw = s16(r[2]) / 100;
const soc_pct = r[4] / 10;
const wmax_lim_pct = r[5] / 100;   // beobachtete §14a-Begrenzung in %
const grid_conn_kw = r[6] / 100;
const grid_limit_kw = Math.round((wmax_lim_pct / 100) * grid_conn_kw * 1000) / 1000;
const reading = {
  ts: new Date().toISOString(),
  power_kw: grid_kw,
  soc_pct,
  pv_power_kw: pv_kw,
  load_kw,
  grid_limit_kw,
};
node.status({ fill: 'green', shape: 'dot', text: 'pv ' + pv_kw.toFixed(1) + ' kW, SoC ' + soc_pct.toFixed(0) + ' %' });
return [{ payload: reading }, { payload: true }];

// Der Sollwert ist bereits durch die Guards des Core begrenzt; hier nur die
// Übersetzung ins Register (int16, 0,01 kW, Zweierkomplement).
const kw = Number(msg.payload);
if (!isFinite(kw)) { return null; }
const raw = Math.round(kw * 100) & 0xffff;
msg.payload = { value: raw, fc: 6, unitid: 1, address: 40, quantity: 1 };
node.status({ fill: 'blue', shape: 'dot', text: (msg.setpoint && msg.setpoint.source || '?') + ' -> ' + kw.toFixed(1) + ' kW' });
return msg;
